package com.example.tailormate;

import androidx.annotation.NonNull;

/** Model: one row of the customers table. */
public class Customer {
    private long _id;
    private String _name;
    private String _phone;
    private String _address;
    private String _notes;
    private String _photoPath;
    private String _createdAt;

    public Customer() { }

    // Used when creating a new customer (id is generated by SQLite)
    public Customer(String name, String phone, String address, String notes) {
        this._name = name;
        this._phone = phone;
        this._address = address;
        this._notes = notes;
    }

    public long getID() { return _id; }
    public void setID(long id) { this._id = id; }
    public String getName() { return _name; }
    public void setName(String name) { this._name = name; }
    public String getPhone() { return _phone; }
    public void setPhone(String phone) { this._phone = phone; }
    public String getAddress() { return _address; }
    public void setAddress(String address) { this._address = address; }
    public String getNotes() { return _notes; }
    public void setNotes(String notes) { this._notes = notes; }
    public String getPhotoPath() { return _photoPath; }
    public void setPhotoPath(String photoPath) { this._photoPath = photoPath; }
    public String getCreatedAt() { return _createdAt; }
    public void setCreatedAt(String createdAt) { this._createdAt = createdAt; }

    @NonNull
    @Override
    public String toString() {
        return _name + "\n" + _phone;
    }
}
